We formalize this explicitly to make the exposition clear based on your comments.
 We begin by noting that the above objective is equivalent to

$$
\mathrm{argmax}\_{\psi} \, \mathbb{E}\_{\mathbf{x}\_{\text{obs}} \sim p\_{\text{true}}} \, \mathbb{E}\_{p\_{\text{true}}(\theta,\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}} )} [\log\, r\_{\psi}(\theta,\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})] \\
= \mathrm{argmax}\_{\psi} \, \mathbb{E}\_{(\mathbf{x}\_{\text{obs}}, \theta, \mathbf{x}\_{\text{mis}}) \sim p\_{\text{true}}} \, [\log\, r\_{\psi}(\theta,\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})]$$

Typically, in realistic scenarios,  we do not know $p\_{\text{true}}(\mathbf{x}\_{\text{mis}})$, but can only assume access to samples $(\mathbf{x}\_{\text{obs}}, \theta) \sim p_{\text{true}}$. Therefore, we treat $\mathbf{x}\_{\text{mis}}$ as latent variables sampled from some tractable (e.g., Gaussian) distribution $p(\cdot|\mathbf{x}\_{\text{obs}})$  conditioned on $\mathbf{x}\_{\text{obs}}$, and resort to a variational approximation. 

Specifically, we maximize a lower bound on 
$\mathbb{E}\_{(\mathbf{x}\_{\text{obs}}, \theta) \sim p\_{\text{true}}} \, [\log\, r\_{\psi}(\theta \mid \mathbf{x}\_{\text{obs}})]$. Formally, we have

\begin{align}
\mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \log r\_{\psi}(\theta \mid \mathbf{x}\_{\text{obs}}) = \mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \log \int r\_{\psi}(\theta,\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})d\mathbf{x}\_{\text{mis}} \\\\
= \mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \log \int \frac{p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})r\_{\psi}(\theta,\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})}{p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} d\mathbf{x}\_{\text{mis}} \\\\
\geq \mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \mathbb{E}\_{\mathbf{x}\_{\text{mis}} \sim p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \left[\log  \frac{r\_{\psi}(\theta,\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})}{p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \right] \\\\
= \mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \mathbb{E}\_{\mathbf{x}\_{\text{mis}} \sim p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \left[\log  \frac{r\_{\psi}(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}}) r\_{\psi}(\theta \mid \mathbf{x}\_{\text{obs}}, \mathbf{x}\_{\text{mis}})}{p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \right]
\end{align}

where we invoked the Jensen's inequality to swap the log and the conditional expectation. Splitting parameters $\psi$ into imputation parameters $\varphi$ and inference parameters $\phi$, and denoting the corresponding imputation and inference networks by $\hat{p}\_{\varphi}$ and $q\_{\phi}$ respectively, we immediately get

\begin{align}
\mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \log r\_{\phi, \varphi}(\theta \mid \mathbf{x}\_{\text{obs}}) \geq  \mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \mathbb{E}\_{\mathbf{x}\_{\text{mis}} \sim p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \left[\log  \frac{\hat{p}\_{\varphi}(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}}) q\_{\phi}(\theta \mid \mathbf{x}\_{\text{obs}}, \mathbf{x}\_{\text{mis}})}{p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \right]
\end{align}

Thus, we obtain the following variational objective:

\begin{align}
 \mathrm{argmax}\_{\phi, \varphi}   \mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \mathbb{E}\_{\mathbf{x}\_{\text{mis}} \sim p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \left[\log  \frac{\hat{p}\_{\varphi}(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}}) q_{\phi}(\theta \mid \mathbf{x}\_{\text{obs}}, \mathbf{x}\_{\text{mis}})}{p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \right] 
\end{align}

\begin{align}
= \mathrm{argmax}\_{\phi, \varphi}  \mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \left(\mathbb{E}\_{\mathbf{x}\_{\text{mis}} \sim p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \left[\log  \hat{p}\_{\varphi}(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}}) + \log q\_{\phi}(\theta \mid \mathbf{x}\_{\text{obs}}, \mathbf{x}\_{\text{mis}})\right] + \mathbb{H}(p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})\right) 
\end{align}

\begin{align}
 =  \mathrm{argmax}\_{\phi, \varphi} \mathbb{E}\_{(\mathbf{x}\_{\text{obs}},\theta) \sim p\_{\text{true}}} \mathbb{E}\_{\mathbf{x}\_{\text{mis}} \sim p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})} \left[\log  \underbrace{\hat{p}\_{\varphi}(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})}\_{\text{imputation}} + \log \underbrace{q\_{\phi}(\theta \mid \mathbf{x}\_{\text{obs}}, \mathbf{x}\_{\text{mis}})}\_{\text{inference}}\right]~,
\end{align}

since the entropy term $\mathbb{H}(p(\mathbf{x}\_{\text{mis}} \mid \mathbf{x}\_{\text{obs}})$ does not depend on the optimization variables $\phi$ and $\varphi$.

This is exactly the objective that we optimize for. Based on your comment, we have now revised section 3.2, Proposition 2, and it's proof in Appendix A.2.2 in the paper to make this clear.

